{
 "summary": "The file has two sorried statements. `not_erdos_146` says Erdős's degeneracy conjecture (bipartite r-degenerate H gives ex(n,H) = O(n^{2-1/r}), for all r>0) is false, and this is a faithful formalization. `twoDegenerateExtremalCounterexample` is meant to say that some graph H on Fin q is connected, bipartite, 2-degenerate, has both colour-class max degrees above 2, and has ex(n,H) ≥ c n^{3/2+ε}. It is instead stated with `∀ q H`, so it claims this for every graph on every Fin q, which is false (for example q = 0).",
 "glossary": [
  {"decl": "TwoDegenerateGraphs.neighborsWithin", "line": 8, "plain": "The neighbours of v inside the vertex set s (s filtered by G.Adj v).", "standard_concept": "Neighbourhood in the induced subgraph G[s]", "matches_standard": "yes", "note": ""},
  {"decl": "TwoDegenerateGraphs.IsDegenerate", "line": 13, "plain": "Every nonempty finite vertex set s contains a vertex with at most r neighbours inside s.", "standard_concept": "r-degenerate graph (every nonempty subgraph has a vertex of degree ≤ r)", "matches_standard": "yes", "note": "Checking induced subgraphs is equivalent to checking all subgraphs, since deleting edges only lowers degrees."},
  {"decl": "TwoDegenerateGraphs.IsTwoDegenerate", "line": 17, "plain": "IsDegenerate 2.", "standard_concept": "2-degenerate", "matches_standard": "yes", "note": ""},
  {"decl": "TwoDegenerateGraphs.DegeneracyConjectureStatement", "line": 20, "plain": "For all r>0, all q and all bipartite r-degenerate H on Fin q, ex(n,H) = O(n^{2-1/r}) as n→∞.", "standard_concept": "Erdős's degeneracy conjecture (3): ex(n,H) = O(n^{2-1/r}) for bipartite r-degenerate H", "matches_standard": "yes", "note": "Uses Mathlib's `extremalNumber`. The cast ((2:ℕ):ℝ) is harmless. The conjecture is not restricted to connected H, which matches the paper's statement of (3)."}
 ],
 "lean_claims": [
  {"theorem": "TwoDegenerateGraphs.twoDegenerateExtremalCounterexample", "line": 28, "plain": "For EVERY q and EVERY graph H on Fin q: H is connected, bipartite and 2-degenerate; for every proper 2-colouring and each colour, the max degree on that colour class exceeds 2; and there exist c, ε > 0 with c·n^{3/2+ε} ≤ ex(n,H) for all large n. This is false as written, e.g. for q = 0, where Connected fails because it needs a nonempty vertex set."},
  {"theorem": "TwoDegenerateGraphs.not_erdos_146", "line": 43, "plain": "It is not the case that for all r>0 and all bipartite r-degenerate H on Fin q, ex(n,H) = O(n^{2-1/r})."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist a fixed connected bipartite 2-degenerate graph H and constants c, ε > 0 with ex(n,H) ≥ c n^{3/2+ε} for all sufficiently large n."},
  {"ref": "Introduction (degeneracy conjecture)", "plain": "Erdős's conjecture that bipartite r-degenerate H have ex(n,H) = O(n^{2-1/r}) is disproved, already for r = 2."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.2", "lean_theorem": "TwoDegenerateGraphs.twoDegenerateExtremalCounterexample", "relation": "different", "why": "The paper has an existential statement over H, but the Lean statement has `∀ q H`, which is unprovable. It also adds an extra conjunct about colour-class max degrees > 2, which is not part of Theorem 1.2 in the excerpt."},
  {"paper_ref": "Disproof of Erdős degeneracy conjecture", "lean_theorem": "TwoDegenerateGraphs.not_erdos_146", "relation": "equivalent", "why": "It is the negation of the conjecture for all r; the paper disproves it via the r = 2 counterexample."},
  {"paper_ref": "Theorem 1.1 (compactness)", "lean_theorem": null, "relation": "not_formalized", "why": "Covered elsewhere (sibling file)."}
 ],
